# 振分表にあって販売場所ではない列。今までは設定値 ITEM_QUANTITY_IGNORED_LOCATIONS で読み飛ばしていた
IGNORED_DEFAULT = "なだや,武相,本町一丁目,千代田"


def seed_allocation(apps, schema_editor):
    """振分の並びを今の並び（販売場所No.順）で埋め、読み飛ばしていた列を振分だけの項目として末尾に足す。"""
    SalesLocation = apps.get_model("sales", "SalesLocation")
    AllocationExtra = apps.get_model("sales", "AllocationExtra")
    order = 0
    for loc in SalesLocation.objects.order_by("no", "id"):
        order += 1
        loc.allocation_order = order
        loc.save(update_fields=["allocation_order"])
    location_names = set(SalesLocation.objects.values_list("name", flat=True))
    raw = os.environ.get("ITEM_QUANTITY_IGNORED_LOCATIONS", IGNORED_DEFAULT)
    for name in [n.strip() for n in raw.split(",") if n.strip()]:
        if name in location_names or AllocationExtra.objects.filter(name=name).exists():
            continue
        order += 1
        AllocationExtra.objects.create(name=name, allocation_order=order)


